        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Тестілеуші не істейді\nТестілеу (Software testing) — тек «баг іздеу» емес. Тестілеуші талаптар мен өнімді зерттеп, қалай **болуы керек** екенін қалай **бар** екенімен салыстырады. Рет әрдайым бірдей:\n1. **Ереже** — талапты табамыз. Мысал: CAT-02 «1.0 нұсқасында M көлеміндегі 6 сусын».\n2. **Әрекет** — ережені тексеретін нәрсені жасаймыз: мәзірді ашып, карточкаларды санаймыз.\n3. **Салыстыру** — күтілетін нәтиже (ереже бойынша) мен нақты нәтиже (экранда).\n4. **Қорытынды** — «сәйкес келді» не «айырмашылық бар — нақты қандай».\n\nСәйкес келу де нәтиже: тексеру ереженің орындалатынын растады.\n\n### QA, QC және тестілеу\n| Сөз | Мағынасы | Мысал |\n|---|---|---|\n| QA (Quality Assurance) — сапаны қамтамасыз ету | қате басынан аз болуы үшін процесті жақсартамыз | әзірлеуге дейін талаптарға сұрақ қоюға келістік |\n| QC (Quality Control) — сапаны бақылау | дайын нәтижені тексереміз | дайын нұсқаның мәзірін талаптар бойынша тексердік |\n| Тестілеу | нақты тексерулер, QC бөлігі | сусындарды санап, CAT-02-мен салыстырдық |\n\n### Бұл әлі баг болмаған кезде\nЕреже түсініксіз не жоқ болса — алдымен менторға сұрақ қоямыз. Ереже не макетсіз «маған түс ұнамайды» — бұл баг емес, пікір."
