        "codeNote": "",
        "more": "Тестілеудің жеті принципі — тестілеушінің неге дәл осылай жұмыс істейтінін түсіндіретін қысқа ережелер. Оларды жаттап емес, мағынасы бойынша білген пайдалы: әрқайсысы не істеу керегін көрсетеді.\n\n### 1. Тестілеу ақаулар барын көрсетеді, бірақ олардың жоқтығын дәлелдемейді\nТексеру қатені таба алады, бірақ басқа қате жоқ екеніне кепілдік бере алмайды.\n**Мысал.** Капучино қосуды тексердің — бәрі сәйкес келді. Бұл себет барлық сусын мен сан үшін жұмыс істейді дегенді білдірмейді.\n**Не істеу керек:** қорытындыда «баг жоқ» емес, **нақты нені** тексергеніңді жаз.\n\n### 2. Толық тестілеу мүмкін емес\nБарлық үйлесімді тексеру мүмкін емес: олар тым көп.\n**Мысал.** 12 сусын × 3 өлшем × 1–10 саны × 2 тіл — тек себетке қосудың өзі 720 нұсқа.\n**Не істеу керек:** маңызды тексерулерді тәуекел бойынша және тест-дизайн тәсілдерімен таңда (кластар мен шекаралар — 9-сабақ).\n\n### 3. Ерте тестілеу уақыт пен ақшаны үнемдейді\nҚате неғұрлым ерте табылса, оны түзету соғұрлым арзан.\n**Мысал.** Әзірлеуге дейінгі «6 сусынның көлемі бірдей ме?» деген сұрақ бір минут тұрады. Мұны шығарғаннан кейін байқасаң — карточкаларды, деректерді және тексерулерді қайта жасау керек.\n**Не істеу керек:** дайын сайтты күтпей, талаптар мен макеттерді бірден оқы.\n\n### 4. Ақаулар шоғырланады\nҚателер жиі бір жерлерге жиналады — әдетте логикасы күрделі жерге.\n**Мысал.** Тапсырыс рәсімдеуде бір өріспен мәселе табылды. Сол форманың көрші өрістерінде тағы бір мәселе табылу ықтималдығы сайттың төменгі бөлігіне қарағанда жоғары.\n**Не істеу керек:** мәселе тапсаң, сол бөлімді мұқиятырақ тексер.\n\n### 5. Пестицид парадоксы\nБір тексерулерді қайталай берсең, олар жаңа ештеңе таппай қалады — жәндіктер бір уға үйреніп кеткендей.\n**Мысал.** Бір ай бойы тек «1 капучино қосуды» тексердік. Тексеру әрдайым жасыл, ал сайттың басқа бөліміндегі қатені ешкім көрмеді.\n**Не істеу керек:** тексерулерді жаңарт: басқа деректер, сценарийлер мен бөлімдер қос.\n\n### 6. Тестілеу контекстке байланысты\nНені және қалай тексеру өнімге байланысты.\n**Мысал.** Кофехана үшін ең бастысы — дұрыс сома және түсінікті рәсімдеу. Банк үшін — қауіпсіздік те, ойын үшін — жылдамдық пен басқару ыңғайлылығы.\n**Не істеу керек:** алдымен дәл осы өнім мен оның пайдаланушылары үшін не маңызды екенін түсін.\n\n### 7. Қатенің болмауы өнімді пайдалы етпейді\nСайт бір де баг болмай жұмыс істеп, бәрібір адамдарға сай келмеуі мүмкін.\n**Мысал.** Барлық тексеру өтті, бірақ тапсырысты тек 15 қадаммен беруге болады — қонақтар бәсекелестерге кетеді.\n**Не істеу керек:** «ереже бойынша жұмыс істей ме» дегенді ғана емес, «пайдаланушы мәселесін шеше ме» дегенді де тексер (мұны валидация деп атайды)."
