        "codeNote": "",
        "more": "### Три слова — три разные вещи\nОшибку, дефект и сбой легко перепутать, но это разные звенья одной цепочки: **человек ошибся → в программе появился дефект → при работе случился сбой**.\n\n| Термин | Что это | Где находится | Учебный пример |\n|---|---|---|---|\n| Ошибка (Error, mistake) | неверное действие человека | в голове или в документе | аналитик написал «5 напитков» вместо согласованных 6 |\n| Дефект, баг (Defect, bug) | неверное место в продукте | в коде, данных или требовании | ссылке «Контакты» в коде указали адрес меню |\n| Сбой (Failure) | видимое неправильное поведение | на экране, при работе | гость нажал «Контакты», а открылось меню |\n\n### Что видит тестировщик\nТестировщик чаще всего видит **сбой** — то, что происходит на экране. Причину (дефект в коде) ищет разработчик. Поэтому в записи пиши то, что наблюдал: «нажал „Контакты“ — открылось меню». Причину вроде «в коде неверная ссылка» помечай как гипотезу, пока её не подтвердили.\n\n### Что считается багом\nБаг — расхождение с **согласованным** правилом: требованием, макетом или явным ожиданием пользователя. Не баг:\n- правило не нарушено, но тебе не нравится (вкус);\n- правила нет — это вопрос к ментору;\n- открыта не та версия сайта — сначала проверь версию."
