        "codeNote": "",
        "more": "### Үш сөз — үш түрлі нәрсе\nҚатені, ақауды және іркілісті шатастыру оңай, бірақ бұлар бір тізбектің әртүрлі буындары: **адам қателесті → бағдарламада ақау пайда болды → жұмыс кезінде іркіліс болды**.\n\n| Термин | Бұл не | Қайда болады | Оқу мысалы |\n|---|---|---|---|\n| Қате (Error, mistake) | адамның дұрыс емес әрекеті | ойда не құжатта | талдаушы келісілген 6 орнына «5 сусын» деп жазды |\n| Ақау, баг (Defect, bug) | өнімдегі дұрыс емес орын | кодта, деректерде не талапта | кодта «Байланыс» сілтемесіне мәзір мекенжайы жазылған |\n| Іркіліс (Failure) | көрінетін дұрыс емес әрекет | экранда, жұмыс кезінде | қонақ «Байланыс» басты, мәзір ашылды |\n\n### Тестілеуші нені көреді\nТестілеуші көбіне **іркілісті** — экранда болатынды көреді. Себебін (кодтағы ақауды) әзірлеуші іздейді. Сондықтан жазбаға бақылағаныңды жаз: «„Байланыс“ бастым — мәзір ашылды». «Кодта сілтеме қате» сияқты себепті расталмайынша болжам деп белгіле.\n\n### Нені баг деп санаймыз\nБаг — **келісілген** ережемен айырмашылық: талаппен, макетпен не пайдаланушының анық күтуімен. Баг емес:\n- ереже бұзылмаған, бірақ саған ұнамайды (талғам);\n- ереже жоқ — бұл менторға сұрақ;\n- сайттың басқа нұсқасы ашылған — алдымен нұсқаны тексер."
