        "code": "",
        "codeNote": "",
        "more": "### Одна проверка — несколько признаков\nВид тестирования — это не «отдельная проверка», а признак, по которому её описывают. Как человека описывают по возрасту, городу и профессии, так и проверку описывают сразу с нескольких сторон. «Открыть меню и добавить капучино» — ручная, функциональная, системная проверка методом чёрного ящика.\n\n| Признак | Вопрос себе | Варианты |\n|---|---|---|\n| Что проверяем | Что сайт делает — или как он это делает? | функциональное / нефункциональное |\n| Кто выполняет | Нажимает человек или программа? | ручное / автоматизированное |\n| Уровень | Маленькая часть или весь путь? | модульный, интеграционный, системный, приёмочный |\n| Знание кода | Смотрим в код или только на экран? | чёрный, белый, серый ящик |\n\n### Функциональное и нефункциональное\n**Функциональное** проверяет, **что** делает продукт: добавляется ли товар, считается ли сумма, отклоняется ли пустое поле. **Нефункциональное** — **как** он это делает: скорость, удобство, отображение на телефоне, перевод, доступность. В требованиях 1.0 правило PRD-01 («выбранное количество добавляется в корзину») функциональное, а UI-01 («на 375–1440 px без горизонтальной прокрутки») — нефункциональное.\n\n### Ручное и автоматизированное\nРучную проверку выполняет человек, автоматизированную — программа-автотест по тем же шагам. Это разница в исполнителе, а не в важности: человек замечает неожиданное, автотест без устали повторяет одно и то же. Автотесты — на парах 14–17."
