        "steps": [],
        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Какой кусок продукта проверяем\nУровень тестирования отвечает на вопрос «насколько большую часть программы мы проверяем». Удобно представить капучино:\n\n- **Модульный (Unit)** — одна маленькая часть отдельно, как проверить только молоко. Обычно пишут разработчики в коде. Пример: функция, которая превращает 1200 в «1 200 ₸».\n- **Интеграционный (Integration)** — две части вместе, как молоко с кофе. Пример: товар, добавленный на карточке, появляется в данных корзины.\n- **Системный (System)** — весь продукт целиком, как готовый капучино. Пример: путь меню → корзина → оформление. Почти все ваши проверки на сайте кофейни — системные.\n- **Приёмочный (Acceptance)** — заказчик или пользователь решает, подходит ли продукт, как гость пробует кофе.\n\n### Как не перепутать\nУровень определяет не инструмент, а то, сколько частей участвует. Запрос к API без экрана — не обязательно модульный тест: если запрос проходит через сервер и данные, это уже связь частей. Начинай с вопроса: «что именно сейчас работает — одна функция, две части или весь путь?»"
