        "good": "Сатып алушы бүкіл сайт арқылы тапсырыс береді — жүйелік тексеру. Себет пен тапсырыс сервисі алмасады — интеграциялық.",
        "bad": "Экран жоқ болғандықтан кез келген GET-сұранысты компоненттік тест деу.",
