        "steps": [],
        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Өнімнің қай бөлігін тексереміз\nТестілеу деңгейі «бағдарламаның қаншалықты үлкен бөлігін тексереміз» деген сұраққа жауап береді. Капучиноны елестету ыңғайлы:\n\n- **Модульдік (Unit)** — бір шағын бөлік бөлек, тек сүтті тексергендей. Әдетте әзірлеушілер кодта жазады. Мысал: 1200 санын «1 200 ₸» түріне келтіретін функция.\n- **Интеграциялық (Integration)** — екі бөлік бірге, сүт пен кофе сияқты. Мысал: карточкада қосылған тауар себет деректерінде шығады.\n- **Жүйелік (System)** — бүкіл өнім, дайын капучино сияқты. Мысал: мәзір → себет → тапсырыс жолы. Кофехана сайтындағы тексеруіңнің дерлік бәрі — жүйелік.\n- **Қабылдау (Acceptance)** — тапсырыс беруші не пайдаланушы өнім өзіне сай ма, шешеді, қонақ кофенің дәмін көргендей.\n\n### Қалай шатастырмау керек\nДеңгейді құрал емес, қанша бөлік қатысатыны анықтайды. Экрансыз API сұранысы міндетті түрде модульдік тест емес: сұраныс сервер мен деректерден өтсе, бұл бөліктер байланысы. «Қазір не жұмыс істейді — бір функция ма, екі бөлік пе, бүкіл жол ма?» деп сұрадан баста."
