        "more": "### Знаем ли мы, что внутри\n«Ящик» — это программа. Вопрос в том, видим ли мы её устройство.\n\n- **Чёрный ящик (Black box)** — код не видим. Проверяем «сделал → получил» по требованиям, как обычный покупатель. Так работает большинство тестировщиков на первом этапе и вы на этом курсе.\n- **Белый ящик (White box)** — читаем код и придумываем проверки по нему: например, чтобы каждая ветка условия `if` выполнилась хотя бы раз. Обычно это делают разработчики.\n- **Серый ящик (Gray box)** — знаем часть устройства: видим запросы в DevTools, структуру данных или схему API, но код целиком не читаем.\n\n### Частая ошибка\nОткрыть DevTools и увидеть HTML страницы — ещё не белый ящик: HTML показывает, как страница собрана, но не логику программы. Белый ящик начинается, когда проверки строятся по коду."
