        "codeNote": "",
        "more": "### Ішінде не барын білеміз бе\n«Жәшік» — бұл бағдарлама. Сұрақ — оның құрылысын көреміз бе.\n\n- **Қара жәшік (Black box)** — кодты көрмейміз. Талаптар бойынша «істедім → алдым» тексереміз, қарапайым сатып алушы сияқты. Бастапқы кезеңде тестілеушілердің көбі және сен осы курста осылай жұмыс істейсің.\n- **Ақ жәшік (White box)** — кодты оқып, тексерулерді соған қарап ойлаймыз: мысалы, `if` шартының әр тармағы кемі бір рет орындалсын. Әдетте мұны әзірлеушілер жасайды.\n- **Сұр жәшік (Gray box)** — құрылғының бір бөлігін білеміз: DevTools-та сұраныстарды, деректер құрылымын не API сызбасын көреміз, бірақ кодты толық оқымаймыз.\n\n### Жиі қате\nDevTools ашып, беттің HTML-ін көру — әлі ақ жәшік емес: HTML беттің қалай құрастырылғанын көрсетеді, бағдарлама логикасын емес. Ақ жәшік тексерулер кодқа қарап құрылғанда басталады."
