        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### SDLC — путь продукта\nЖизненный цикл разработки удобно сравнить со стройкой дома: проект (**требования**) → чертежи (**дизайн**) → стройка (**разработка**) → приёмка (**тестирование**) → заселение (**релиз**) → ремонт (**поддержка**). В реальной работе этапы часто повторяются по кругу: после релиза приходят новые идеи, и всё начинается снова.\n\n### Где работает тестировщик\n| Этап | Что делает QA |\n|---|---|\n| Требования | задаёт вопросы к неясным правилам |\n| Дизайн | смотрит макеты: все ли состояния экрана нарисованы |\n| Разработка | готовит проверки и тестовые данные |\n| Тестирование | выполняет проверки и оформляет баги |\n| Релиз | быстро проходит главный путь на рабочем сайте |\n| Поддержка | проверяет исправления и новые доработки |\n\nЧем раньше найдена ошибка, тем дешевле: вопрос к требованию стоит минуту, исправление после релиза — дни работы.\n\n### STLC — путь работы тестировщика\nИзучить требования → спланировать → подготовить проверки → выполнить → отчитаться. Как покупка подарка: узнал, что нужно → решил, куда идти → составил список → сходил → рассказал, что купил и чего не нашёл. Последний шаг важен: отчёт говорит и о том, что **не** проверено."
