        "short": "Agile — работать небольшими шагами и учитывать обратную связь. Scrum организует работу спринтами. Kanban показывает поток задач и ограничивает незавершённую работу. Пример доски: Backlog → To do → In progress → Review → Done; названия команда выбирает сама.",
