        "codeNote": "",
        "more": "### Водопад и Agile\n**Водопад (Waterfall)** — этапы строго по очереди: сначала все требования, потом весь дизайн, вся разработка и только в конце тестирование. Ошибку в требованиях находят, когда всё уже построено.\n\n**Agile** — подход «маленькими шагами с частым показом заказчику». Вместо одного дома за год строим по комнате каждые две недели: ошибки и неудачные идеи видны раньше.\n\n### Scrum и Kanban — два способа работать по Agile\n| | Scrum | Kanban |\n|---|---|---|\n| Ритм | спринты по 1–4 недели (чаще 2) | непрерывный поток, без спринтов |\n| План | в начале спринта выбирают задачи и цель | задачи берут по одной, когда освободилось место |\n| Ограничение | объём спринта | число задач «в работе» (WIP-лимит) |\n| Встречи | планирование, ежедневная встреча (daily), показ результата, ретроспектива | по договорённости команды |\n\nAgile и Scrum — не одно и то же: Agile — общий подход (как «здоровый образ жизни»), Scrum — конкретная программа тренировок.\n\n### Доска задач\nКолонки показывают состояние работы: **Backlog** — запас идей, **To do** — выбрали в ближайшую работу, **In progress** — делаем, **Review** — проверяем результат, **Done** — сделано и проверено. Карточку двигают, только когда работа действительно перешла в следующее состояние."
