        "code": "",
        "codeNote": "",
        "more": "### Тест-кейс — как рецепт\nТест-кейс — пошаговая инструкция проверки **одной** вещи. Предусловия — «разогрей духовку», тестовые данные — ингредиенты, шаги — порядок действий, ожидаемый результат — «корочка золотистая». Хороший тест-кейс выполнит любой человек без подсказок автора и получит тот же результат.\n\n### Поля\n| Поле | Что писать | Пример |\n|---|---|---|\n| ID | тип + раздел + номер | TC-CRT-001 |\n| Название | что проверяем, одной фразой | Удаление единственного товара из корзины |\n| Предусловия | состояние до первого шага; не нужно — удали | в корзине один латте |\n| Тестовые данные | значения; не нужны — удали | — |\n| Шаги | по одному действию, нумерованные | 1. Открыть корзину. 2. Нажать «Удалить» у латте |\n| Ожидаемый результат | по правилу, с номером правила | корзина пуста, есть ссылка в меню (CRT-05) |\n| Фактический результат | только после выполнения | корзина пуста, есть ссылка в меню |\n| Статус | Not run → Passed / Failed / Blocked / Skipped | Passed |\n\n### Четыре правила\n- **Одна цель:** иначе при провале непонятно, что сломалось.\n- **Конкретные шаги:** «нажать „Добавить“ на карточке „Латте“», а не «добавить товар».\n- **Проверяемое ожидание из правила:** не «всё работает», не списано с экрана.\n- **Независимость:** всё нужное заранее — в предусловия, чтобы кейс выполнялся в любом порядке.\n\nОбычно в кейсе 3–8 шагов. Если получается 20 — раздели на несколько кейсов. Набор кейсов по одной функции называют **тест-сьютом (test suite)**.",
