        "more": "### Тест-кейс — рецепт сияқты\nТест-кейс — **бір** нәрсені тексерудің қадамдық нұсқаулығы. Алғышарттар — «пешті қыздыр», тест деректері — ингредиенттер, қадамдар — әрекет реті, күтілетін нәтиже — «қабығы алтын түсті». Жақсы тест-кейсті кез келген адам автордың кеңесінсіз орындап, сол нәтижені алады.\n\n### Өрістер\n| Өріс | Не жазу керек | Мысал |\n|---|---|---|\n| ID | түрі + бөлім + нөмір | TC-CRT-001 |\n| Атауы | нені тексереміз, бір сөйлеммен | Себеттегі жалғыз тауарды жою |\n| Алғышарттар | бірінші қадамға дейінгі күй; керек емес — өшір | себетте бір латте |\n| Тест деректері | мәндер; керек емес — өшір | — |\n| Қадамдар | бір-бір әрекеттен, нөмірленген | 1. Себетті ашу. 2. Латтедегі «Жою» басу |\n| Күтілетін нәтиже | ереже бойынша, ереже нөмірімен | себет бос, мәзірге сілтеме бар (CRT-05) |\n| Нақты нәтиже | тек орындағаннан кейін | себет бос, мәзірге сілтеме бар |\n| Мәртебе | Not run → Passed / Failed / Blocked / Skipped | Passed |\n\n### Төрт ереже\n- **Бір мақсат:** әйтпесе өтпей қалғанда не бұзылғаны түсініксіз.\n- **Нақты қадамдар:** «тауар қосу» емес, «„Латте“ карточкасында „Қосу“ басу».\n- **Ережеден алынған тексерілетін күту:** «бәрі жұмыс істейді» емес, экраннан көшірілмеген.\n- **Тәуелсіздік:** алдын ала керектің бәрі — алғышарттарға, кейс кез келген ретпен орындалсын.\n\nӘдетте кейсте 3–8 қадам болады. 20 болып кетсе — бірнеше кейске бөл. Бір функцияға арналған кейстер жиынын **тест-сьют (test suite)** деп атайды.",
