        "codeNote": "",
        "more": "### Позитивная и негативная проверка\n**Позитивная** — правильные данные и действия («счастливый путь»): сайт должен выполнить действие. **Негативная** — неправильные данные или действия: сайт не должен ломаться и должен понятно сказать, что не так. Как с ключом: свой открывает дверь; чужой не открывает, а замок при этом не ломается.\n\n### Правильный отказ — это Passed\nНегативная проверка **прошла**, если сайт отказал так, как написано в правиле. Пример по ORD-01 и ORD-02 (1.0): имя пустое → заказ не создан, ошибка рядом с полем — Passed. Failed — если сайт принял запрещённое или сломался.\n\n### Откуда брать негативные данные\n| Приём | Пример |\n|---|---|\n| пустое поле | имя не заполнено |\n| только пробелы | «   » |\n| слишком длинная строка | 300 букв |\n| неверный формат | буквы в телефоне |\n| спецсимволы и эмодзи | «☕☕☕» |\n| ноль и отрицательные числа | количество 0, −1 |\n\nОжидание пишем, **только если есть правило**. В 1.0 известно, что поля обязательны, — значит, понятно, что должно быть с пустыми. Про пробелы или буквы в телефоне правила в 1.0 нет: записываем наблюдение и вопрос ментору. Негативных проверок обычно больше, чем позитивных: ошибиться можно многими способами. Но начинают с позитивной — убедиться, что функция вообще работает."
