        "more": "### Позитивтік және негативтік тексеру\n**Позитивтік** — дұрыс деректер мен әрекеттер («бақытты жол»): сайт әрекетті орындауы керек. **Негативтік** — дұрыс емес деректер не әрекеттер: сайт бұзылмауы және не дұрыс емес екенін түсінікті айтуы керек. Кілт сияқты: өзіңдікі есікті ашады; бөтені ашпайды, ал құлып бұзылмайды.\n\n### Дұрыс бас тарту — Passed\nСайт ережеде жазылғандай бас тартса, негативтік тексеру **өтті**. ORD-01 мен ORD-02 бойынша мысал (1.0): аты бос → тапсырыс жасалмады, өріс жанында қате — Passed. Failed — сайт тыйым салынғанды қабылдаса не бұзылса.\n\n### Негативтік деректерді қайдан алу керек\n| Тәсіл | Мысал |\n|---|---|\n| бос өріс | аты толтырылмаған |\n| тек бос орындар | «   » |\n| тым ұзын жол | 300 әріп |\n| дұрыс емес формат | телефондағы әріптер |\n| арнайы таңбалар мен эмодзи | «☕☕☕» |\n| нөл және теріс сандар | саны 0, −1 |\n\nКүтуді **тек ереже болса** жазамыз. 1.0-де өрістер міндетті екені белгілі — демек, бос өрістермен не болуы керегі түсінікті. Бос орындар не телефондағы әріптер туралы 1.0-де ереже жоқ: бақылау мен менторға сұрақты жазамыз. Негативтік тексерулер әдетте позитивтіктен көп: қателесудің жолы көп. Бірақ позитивтіктен бастайды — функцияның жалпы жұмыс істейтініне көз жеткізу үшін."
