        "good": "«Бос себетте санағыш 0, мәзірге сілтеме бар» — орындап, салыстыруға болады.",
        "bad": "«Себет жақсы болуы керек» — дұрыс нәтиже белгісіз.",
        "mistakes": [
          "Сан, түс, мерзім ойлап таппа. Келісілген ереже жоқ деталь — алдымен сұрақ."
        ],
        "steps": [],
        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Жақсы талап деген не\nТалап — өнімнің не және қалай істеуі керегі туралы шарт. Сайттың әрекетін онымен салыстырады, сондықтан нашар жазылған талап қате тексерулер береді.\n\n| Қасиет | Өзіңе сұрақ | Мәселе мысалы |\n|---|---|---|\n| Толық | бәрі сипатталған ба, қате кезінде не болады? | «Аты міндетті» — бос болса не көрсету керек? |\n| Бірмәнді | бәрі бірдей түсіне ме? | «Пікір тым ұзын емес» — неше таңба? |\n| Қайшылықсыз | ережелер дауласпай ма? | «Телефон міндетті» және «телефон міндетті емес» |\n| Тексерілетін | «иә / жоқ» деп жауап беруге бола ма? | «Ыңғайлы батырма» — тексеру мүмкін емес |\n| Орындалатын | мұны жасауға бола ма? | «1 минутта жеткізу» |\n\n### Тұзақ сөздер\n«Жылдам», «ыңғайлы», «әдемі», «дұрыс», «қажет болса», «т. б.». Әрқайсысына — авторға сұрақ: «Жылдам — бұл неше секунд?» Кофехана талаптарынан жақсы мысал: UI-01 «375–1440 px енінде элементтер көлденең айналдырусыз қолжетімді» — сандар мен тексерілетін шарт бар.\n\n### Макет және прототип\nМакет — болашақ экранның суреті (үйдің суреті), прототип — басуға болатын макет (бөлмелер бойынша 3D-тур). Макетті тексергенде оны талаппен салыстыр, қате сөздерді, батырмалардың әртүрлі стилін және **жетіспейтін экран күйлерін** ізде.\n\nТалаптағы не макеттегі қатені әзірлеуге дейін талдаушыға не дизайнерге **сұрақ не ескерту** ретінде рәсімдейді. Бұл ең арзан баг: код әлі жазылмаған."
