        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### UI — что видно, UX — удобно ли\n**UI (User Interface)** — внешний вид: тексты, кнопки, цвета, выравнивание, картинки. **UX (User Experience)** — насколько легко и понятно гостю выполнить задачу: найти напиток, вернуться в меню, оформить заказ.\n\n| | UI | UX |\n|---|---|---|\n| Вопрос | как выглядит? | удобно ли сделать задачу? |\n| Как проверяют | смотрят на экран, сравнивают с макетом | дают человеку задачу и смотрят, справится ли |\n| Пример | текст кнопки не обрезан, кнопки одного стиля | гость с первого раза находит путь из корзины в меню |\n\n### Наблюдение или баг\nНаблюдение становится багом, только если нарушено правило или макет. «Мне не нравится цвет» — вкус. «Кнопка ниже 44 px, а UI-02 требует не ниже 44 px» (1.5) — расхождение с правилом. Описывая UX-проблему, объясняй, **как она мешает действию**: «гость не видит, как вернуться в меню, и закрывает сайт»."
