        "title": "Классы эквивалентности и граничные значения",
        "short": "Классы эквивалентности объединяют значения с одинаковым ожидаемым поведением. Проверка границ выбирает край и соседние значения. Это экономит проверки без случайного угадывания.",
        "good": "Учебное правило: целый возраст 18–60. Классы: меньше 18, 18–60, больше 60. У границ берём 17, 18, 19 и 59, 60, 61.",
