        "title": "Другие техники тест-дизайна",
        "short": "Техники помогают выбрать проверки. Таблица решений рассматривает сочетания условий; переходы состояний — что меняется после действия; попарная проверка — пары вариантов, когда сочетаний много.",
        "good": "Учебное правило скидки зависит от входа и промокода: проверяем вход да/нет вместе с кодом да/нет — четыре сочетания.",
