        "steps": [],
        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Техники выбора проверок\n| Техника | Когда помогает | Пример |\n|---|---|---|\n| Классы и границы | у поля есть диапазон | количество 1–10 → 0, 1, 10, 11 |\n| Переходы состояний (State transition) | экран меняется после действий | корзина: пусто → добавили → удалили последний → пусто |\n| Таблица решений (Decision table) | результат зависит от нескольких условий | учебная скидка: вход да/нет × промокод да/нет — 4 варианта |\n| Попарное тестирование (Pairwise) | сочетаний слишком много | браузер × язык × экран: 8 сочетаний покрывают 4 проверки |\n| По сценарию (Use case) | важен путь человека целиком | найти латте → добавить → оформить |\n\n### Переходы состояний\nЗаписываем ожидаемое состояние **после каждого** действия, а не только в конце. Так видно, на каком переходе что-то пошло не так.\n\n### Таблица решений\nДля двух условий «да/нет» — четыре сочетания: да+да, да+нет, нет+да, нет+нет. Для каждого **заранее** пишем ожидание. Рисовать таблицу не обязательно — хватит списка. Невозможные сочетания помечаем и не проверяем.\n\n### Попарное тестирование\nЕсли сочетаний сотни, проверяют так, чтобы каждая **пара** значений встретилась хотя бы раз. Это сильно сокращает число проверок, а большинство ошибок возникает именно из-за пары условий."
