        "more": "### Тексеру таңдау тәсілдері\n| Тәсіл | Қашан көмектеседі | Мысал |\n|---|---|---|\n| Кластар мен шекаралар | өрістің ауқымы бар | саны 1–10 → 0, 1, 10, 11 |\n| Күй ауысулары (State transition) | экран әрекеттерден кейін өзгереді | себет: бос → қостық → соңғысын жойдық → бос |\n| Шешімдер кестесі (Decision table) | нәтиже бірнеше шартқа байланысты | оқу жеңілдігі: кіру иә/жоқ × промокод иә/жоқ — 4 нұсқа |\n| Жұптық тестілеу (Pairwise) | үйлесімдер тым көп | браузер × тіл × экран: 8 үйлесімді 4 тексеру қамтиды |\n| Сценарий бойынша (Use case) | адамның бүкіл жолы маңызды | латтені табу → қосу → рәсімдеу |\n\n### Күй ауысулары\nКүтілетін күйді тек соңында емес, **әр** әрекеттен кейін жазамыз. Сонда қай ауысуда бірдеңе дұрыс болмағаны көрінеді.\n\n### Шешімдер кестесі\nЕкі «иә/жоқ» шартына — төрт үйлесім: иә+иә, иә+жоқ, жоқ+иә, жоқ+жоқ. Әрқайсысына күтуді **алдын ала** жазамыз. Кесте салу міндетті емес — тізім жеткілікті. Мүмкін емес үйлесімдерді белгілеп, тексермейміз.\n\n### Жұптық тестілеу\nҮйлесімдер жүздеген болса, мәндердің әр **жұбы** кемі бір рет кездесетіндей тексереді. Бұл тексеру санын қатты азайтады, ал қателердің көбі дәл екі шарттың жұбынан туады."
