        "codeNote": "",
        "more": "### Путь бага\nКак посылка: оформлена (**New**) → назначен курьер (**Open / Assigned**) → в пути (**In Progress**) → доставлена (**Fixed**) → получатель проверяет (**Retest**) → всё в порядке (**Closed**) или вернул (**Reopened**).\n\n| Статус | Что значит | Кто ставит |\n|---|---|---|\n| New | баг найден и описан | тестировщик |\n| Open / Assigned | принят, назначен разработчик | тимлид или менеджер |\n| In Progress | исправляют | разработчик |\n| Fixed | исправление в новой сборке | разработчик |\n| Retest | повторяем шаги на исправленной сборке | тестировщик |\n| Closed | ошибки больше нет | тестировщик |\n| Reopened | ошибка осталась | тестировщик |\n| Rejected | не баг, так задумано | разработчик или менеджер |\n| Duplicate | такой баг уже есть | любой участник |\n| Cannot Reproduce | не повторить по шагам | разработчик |\n\n### Важные правила\n- **Closed** ставит тестировщик и только после проверки: «Fixed» — ещё не доказательство.\n- Если исправленная сборка не выдана, ретест не выполнен — так и пиши. Другой номер версии не доказывает исправление.\n- Если ошибка та же — **Reopened** с новым фактом. Если нашлась **другая** проблема — это новый баг.\n- **Cannot Reproduce** чаще всего значит, что в репорте не хватает шагов, версии или данных.\n- Названия статусов отличаются в разных командах и трекерах; логика одна: нашёл → исправляют → проверил → закрыт или переоткрыт."
