        "code": "",
        "codeNote": "",
        "more": "### Как заявление о пропаже\nБаг-репорт нужен, чтобы другой человек **повторил** проблему с первого раза. Где, когда, что именно, приметы — без этого ничего не найдут.\n\n### Заголовок «Что? Где? Когда?»\nПлохо: «Корзина не работает». Хорошо (учебный пример): «Подвал: время работы 08:00–21:00 вместо 08:00–22:00». По заголовку понятно, что сломано и где, и его легко найти среди других багов.\n\n### Поля по порядку\n1. **ID и заголовок** — BUG-MNU-001 и формула «Что? Где? Когда?».\n2. **Предусловия** и **тестовые данные** — необязательные поля; заполняй, если нужны для повторения.\n3. **Шаги** — с первой страницы, по одному действию, с конкретными данными.\n4. **Ожидаемый результат** — по правилу, с его номером. **Фактический** — что увидел.\n5. **Окружение** — версия сайта, ОС (Win+R → `winver`), браузер с версией (Chrome: ⋮ → Справка → О браузере Google Chrome), ширина экрана, адрес страницы.\n6. **Вложение** — скриншот всей страницы с отмеченным местом (Win+Shift+S) или видео.\n7. **Severity / Priority** — насколько мешает и как срочно (подробно — пара 13).\n\n### Правила\n- Один баг — один репорт.\n- Перед оформлением повтори баг 2–3 раза; если он не всегда повторяется, укажи частоту («2 из 5»).\n- Проверь, нет ли уже такого бага.\n- Пиши нейтрально, только факты. Догадку о причине помечай как гипотезу.",
