        "code": "",
        "codeNote": "",
        "more": "### Жоғалғандықтан арыз сияқты\nБаг-репорт басқа адам мәселені бірінші реттен **қайталауы** үшін керек. Қайда, қашан, нақты не, белгілері — онсыз ештеңе табылмайды.\n\n### «Не? Қайда? Қашан?» тақырыбы\nНашар: «Себет жұмыс істемейді». Жақсы (оқу мысалы): «Төменгі бөлік: жұмыс уақыты 08:00–22:00 орнына 08:00–21:00». Тақырыптан не бұзылғаны және қайда екені түсінікті, оны басқа багтардың ішінен табу оңай.\n\n### Өрістер ретімен\n1. **ID және тақырып** — BUG-MNU-001 және «Не? Қайда? Қашан?» формуласы.\n2. **Алғышарттар** мен **тест деректері** — міндетті емес; қайталауға қажет болса толтыр.\n3. **Қадамдар** — бірінші беттен, бір-бір әрекеттен, нақты деректермен.\n4. **Күтілетін нәтиже** — ереже бойынша, нөмірімен. **Нақты** — не көргенің.\n5. **Орта** — сайт нұсқасы, ОЖ (Win+R → `winver`), нұсқасы бар браузер (Chrome: ⋮ → Анықтама → Google Chrome туралы), экран ені, бет мекенжайы.\n6. **Тіркеме** — орны белгіленген бүкіл беттің скриншоты (Win+Shift+S) не бейне.\n7. **Severity / Priority** — қаншалықты кедергі және қаншалықты шұғыл (толығырақ — 13-сабақ).\n\n### Ережелер\n- Бір баг — бір репорт.\n- Рәсімдеу алдында багты 2–3 рет қайтала; ол әрдайым қайталанбаса, жиілігін көрсет («5-тен 2»).\n- Мұндай баг бұрыннан бар ма, тексер.\n- Бейтарап, тек фактілерді жаз. Себеп туралы болжамды гипотеза деп белгіле.",
