        "short": "Severity — мәселе жұмысқа қаншалықты кедергі. Priority — қаншалықты шұғыл түзету керек. Оқуда бағаңды ұсын да, әсерін түсіндір; соңғы басымдықты команда келіседі.",
        "good": "Ешкім тапсырыс жасай алмайды — әсері ауыр. Баннердегі әріп қатесі аз әсерлі, бірақ акция алдында шұғыл болуы мүмкін.",
