        "more": "### Инструменты разработчика в браузере\nDevTools открываются клавишей **F12** (на ноутбуке **Fn+F12**) или **Ctrl+Shift+I**. Есть только в браузере на компьютере.\n\n| Вкладка | Что показывает | Когда тестировщику нужна |\n|---|---|---|\n| Elements | HTML и CSS выбранного элемента | узнать размер кнопки, цвет, текст |\n| Console | сообщения и ошибки JavaScript | приложить текст красной ошибки к репорту |\n| Network | запросы к серверу и коды ответа | показать, какой ответ пришёл: 200, 404, 500 |\n| Application | данные, сохранённые сайтом в браузере | посмотреть корзину или язык в Local Storage |\n| Режим телефона | сайт на ширине телефона | Ctrl+Shift+M → ширина 360 |\n\n### Важно помнить\n- Network записывает запросы, **только когда DevTools открыты**: сначала F12, потом действие или F5.\n- Красная строка в Console — **факт**, но не доказанная причина бага.\n- Изменения, сделанные в Elements, видишь только ты и только до обновления страницы — это не исправление бага."
