        "more": "### Браузердегі әзірлеуші құралдары\nDevTools **F12** пернесімен (ноутбукта **Fn+F12**) не **Ctrl+Shift+I** арқылы ашылады. Тек компьютердегі браузерде бар.\n\n| Қойынды | Не көрсетеді | Тестілеушіге қашан керек |\n|---|---|---|\n| Elements | таңдалған элементтің HTML мен CSS-і | батырманың өлшемін, түсін, мәтінін білу |\n| Console | JavaScript хабарламалары мен қателері | қызыл қатенің мәтінін репортқа тіркеу |\n| Network | серверге сұраныстар және жауап кодтары | қандай жауап келгенін көрсету: 200, 404, 500 |\n| Application | сайт браузерде сақтаған деректер | Local Storage-тен себетті не тілді қарау |\n| Телефон режимі | телефон еніндегі сайт | Ctrl+Shift+M → ені 360 |\n\n### Есте сақта\n- Network сұраныстарды **DevTools ашық тұрғанда ғана** жазады: алдымен F12, кейін әрекет не F5.\n- Console-дағы қызыл жол — **факт**, бірақ багтың дәлелденген себебі емес.\n- Elements-те жасалған өзгерістерді тек сен және бет жаңартылғанша ғана көресің — бұл багты түзету емес."
