        "steps": [],
        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Зачем трекер\nБаг из чата теряется, карточка в трекере остаётся: её видно всей команде, у неё есть история, исполнитель и ссылка. Популярные трекеры — Jira, YouTrack, Trello; логика одна, отличаются названия кнопок.\n\n| Поле карточки | Что туда пишут |\n|---|---|\n| Заголовок | «Что? Где? Когда?» |\n| Описание | шаги, ожидаемый и фактический результат, окружение, версия |\n| Вложения | скриншот, видео |\n| Метки | серьёзность, раздел |\n| Исполнитель | кто сейчас отвечает |\n| Статус | New, In Progress, Fixed, Retest, Closed, Reopened |\n| Комментарии | что сделали и почему поменяли статус |\n\n### Правила\n- Перед созданием поищи **дубль**.\n- **Одна карточка — один баг**.\n- Статус меняет тот, чья это роль: разработчик — In Progress и Fixed, тестировщик — Closed и Reopened.\n- Каждое изменение статуса — **с комментарием**.\n- В чат и отчёт даём **ссылку** на карточку."
