        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Трекер не үшін\nЧаттағы баг жоғалады, трекердегі карточка қалады: оны бүкіл команда көреді, оның тарихы, орындаушысы және сілтемесі бар. Танымал трекерлер — Jira, YouTrack, Trello; логикасы бір, батырма атаулары әртүрлі.\n\n| Карточка өрісі | Не жазады |\n|---|---|\n| Тақырып | «Не? Қайда? Қашан?» |\n| Сипаттама | қадамдар, күтілетін және нақты нәтиже, орта, нұсқа |\n| Тіркемелер | скриншот, бейне |\n| Белгілер | ауырлық, бөлім |\n| Орындаушы | қазір кім жауапты |\n| Мәртебе | New, In Progress, Fixed, Retest, Closed, Reopened |\n| Пікірлер | не істелді және мәртебе неге өзгерді |\n\n### Ережелер\n- Жасамас бұрын **көшірмесін** ізде.\n- **Бір карточка — бір баг**.\n- Мәртебені сол рөлдегі адам өзгертеді: әзірлеуші — In Progress пен Fixed, тестілеуші — Closed пен Reopened.\n- Мәртебенің әр өзгерісі — **пікірмен**.\n- Чатқа және есепке карточканың **сілтемесін** береміз."
