        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### План как план поездки\nТест-план отвечает на вопросы: куда едем (**что тестируем**), чем (**виды тестирования**), с кем (**команда**), когда (**сроки**), что берём (**окружение**), когда считаем, что приехали (**критерии завершения**), что может пойти не так (**риски**). В итоговом проекте (пара 18) план занимает одну страницу.\n\n| Раздел | Пример для раздела «Корзина», qala coffe 1.5 |\n|---|---|\n| Объём | строки, количество, сумма, удаление, пустая корзина |\n| Вне объёма | оформление и оплата — раздел соседа |\n| Виды тестирования | функциональное, негативное, границы, UI, телефон |\n| Окружение | Chrome и Firefox, 1366 и 360 px |\n| Сроки | документация — пара 16, прогон — 17–19, ретест и регресс — 21–22 |\n| Критерии начала | сайт 1.5 и требования доступны |\n| Критерии завершения | все кейсы выполнены, баги в трекере, отчёт написан |\n| Риски | сайт недоступен; неясное правило — нужен ответ ментора |\n\n### Частые ошибки\n- «Проверю весь сайт до полного отсутствия багов» — это не план: всё проверить нельзя.\n- Критерий завершения «когда найду все баги» никогда не выполнится. Он должен быть достижимым.\n- Без строки «вне объёма» читатель решит, что проверено всё."
