        "more": "### Сапар жоспары сияқты жоспар\nТест-жоспар сұрақтарға жауап береді: қайда барамыз (**нені тестілейміз**), немен (**тестілеу түрлері**), кіммен (**команда**), қашан (**мерзімдер**), не аламыз (**орта**), қашан жеттік деп санаймыз (**аяқтау критерийлері**), не дұрыс болмауы мүмкін (**тәуекелдер**). Қорытынды жобада (18-сабақ) жоспар бір бет алады.\n\n| Бөлім | qala coffe 1.5 «Себет» бөліміне мысал |\n|---|---|\n| Көлем | жолдар, саны, сома, жою, бос себет |\n| Көлемнен тыс | рәсімдеу мен төлем — көршінің бөлімі |\n| Тестілеу түрлері | функционалдық, негативтік, шекаралар, UI, телефон |\n| Орта | Chrome және Firefox, 1366 және 360 px |\n| Мерзімдер | құжаттама — 16-сабақ, өту — 17–19, ретест пен регресс — 21–22 |\n| Бастау критерийлері | 1.5 сайты мен талаптары қолжетімді |\n| Аяқтау критерийлері | барлық кейс орындалды, багтар трекерде, есеп жазылды |\n| Тәуекелдер | сайт қолжетімсіз; түсініксіз ереже — ментордың жауабы керек |\n\n### Жиі қателер\n- «Баг мүлде жоқ болғанша бүкіл сайтты тексеремін» — бұл жоспар емес: бәрін тексеру мүмкін емес.\n- «Барлық багты тапқанда» деген аяқтау критерийі ешқашан орындалмайды. Ол қол жеткізілетін болуы керек.\n- «Көлемнен тыс» жолынсыз оқырман бәрі тексерілді деп ойлайды."
