        "more": "### Что такое окружение\nОкружение (Test environment) — условия, в которых ты видел результат. Один и тот же баг может повторяться только в одном браузере, только на узком экране или только в одной версии сайта. Без окружения разработчик не сможет повторить проверку.\n\n| Что указать | Как узнать | Пример |\n|---|---|---|\n| Операционная система | Win+R → `winver` → Enter | Windows 11 |\n| Браузер и версия | Chrome: ⋮ → Справка → О браузере Google Chrome | Chrome 131 |\n| Ширина окна | на телефоне — модель; в DevTools — ширина в режиме телефона | 1280 px / 375 px |\n| Адрес страницы | Ctrl+L, затем Ctrl+C | …/cart.html?version=1.5 |\n| Версия сайта | переключатель версии в шапке кофейни | 1.5 |\n| Сборка | номер, если его выдали | не указывать, если не выдан |\n\n### Правила\n- Пиши **свои** значения, не копируй версию браузера из чужого примера.\n- Не выдумывай номер сборки: если его нет, так и напиши.\n- Для мобильной проблемы уточни: настоящий телефон или режим телефона в DevTools. Это разные условия.\n- **Тестовый стенд (staging)** — учебная копия сайта для проверок, **прод (production)** — сайт для настоящих гостей. На курсе вы работаете со стендом."
