        "good": "10 минуттық мақсат: мәзір → себет → кері өтуде тауар жоғала ма? Әрекет пен бақылауды жазу.",
        "bad": "Мақсатсыз жарты сағат кездейсоқ басып, табылған мәселе қадамын сақтамау.",
        "mistakes": [
          "Зерттеуді ретсіздікпен шатастырма. Сәйкестік пен сұрақ та пайдалы."
        ],
        "steps": [],
        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Мақсатпен зерттейміз\nЗерттеушілік тестілеу — өнімді зерттейміз, тексерулерді ойлап табамыз және орындаймыз. Оны «кез келгенін басудан» **мақсат**, **уақыт** және **жазбалар** ажыратады.\n\n### Чартер және сессия\n**Чартер** — бір сөйлемдегі мақсат: «**[Нені]** **[неміне]** арқылы зерттеу, **[қандай мәселелерді]** табу үшін». Мысал: «Түсініксіз қателерді табу үшін рәсімдеу формасын бос және ұзын мәндер арқылы зерттеу». **Сессия** — бір чартер бойынша жұмыс, әдетте 20–25 минут.\n\n### Эвристикалар — неден бастау керек\n- батырманы қатарынан екі рет басу;\n- әрекет ортасында «Артқа» не F5;\n- бос, өте ұзын және оғаш мәндер;\n- әрекетті үзіп, қайта оралу;\n- сценарий ортасында тілді не экран енін ауыстыру.\n\n### Сессиядан кейін\nӘр табылғанды **багқа** (ереже бар), **сұраққа** (ереже жоқ) не **сәйкестікке** жатқызамыз. Пайдалы тексерулерді **жаңа тест-кейстерге** айналдырамыз."
