        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Разные браузеры\nБраузеры — как разные переводчики одного кода: обычно одинаково, иногда по-разному. Chrome и Edge построены на одном движке, поэтому для второй проверки лучше взять **Firefox**, а на iPhone — **Safari**.\n\n### Разные экраны\nАдаптивная страница подстраивается под ширину, как одежда, которая тянется. Типичные ширины: телефон **360–390 px**, планшет **768 px**, ноутбук **1366 px**, монитор **1920 px**. Сайт считает ширину в CSS-пикселях: телефон с экраном 1080 точек и масштабом 3 для сайта шириной 360.\n\n| Что проверять | Плохой признак |\n|---|---|\n| текст | обрезается или налезает |\n| прокрутка | страницу двигают вбок |\n| кнопки | меньше 44 px, трудно нажать |\n| формы | поле скрыто или неудобно |\n| картинки | растянуты |\n\n### Окружение в репорте\nОбязательно: браузер **с версией**, ширина окна, язык; для телефона — модель и что это **настоящий телефон**, а не эмуляция в DevTools."
