        "steps": [],
        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Әртүрлі браузерлер\nБраузерлер — бір кодтың әртүрлі аудармашылары сияқты: әдетте бірдей, кейде басқаша. Chrome мен Edge бір қозғалтқышта жасалған, сондықтан екінші тексеруге **Firefox**-ты, ал iPhone-да **Safari**-ды алған жақсы.\n\n### Әртүрлі экрандар\nБейімделгіш бет енге қарай өзгереді, созылатын киім сияқты. Әдеттегі ендер: телефон **360–390 px**, планшет **768 px**, ноутбук **1366 px**, монитор **1920 px**. Сайт енді CSS-пиксельмен есептейді: 1080 нүктелі экраны және масштабы 3 болатын телефон сайт үшін 360 ені.\n\n| Нені тексеру керек | Нашар белгі |\n|---|---|\n| мәтін | қиылады не бір-біріне шығады |\n| айналдыру | бетті жанына жылжытады |\n| батырмалар | 44 px-тен кіші, басу қиын |\n| формалар | өріс жасырын не ыңғайсыз |\n| суреттер | созылған |\n\n### Репорттағы орта\nМіндетті: **нұсқасы бар** браузер, терезе ені, тіл; телефон үшін — үлгісі және бұл DevTools-тағы эмуляция емес, **нақты телефон** екені."
