        "more": "### Четыре проверки — четыре вопроса\n| Проверка | Вопрос | Пример |\n|---|---|---|\n| Smoke | новая сборка вообще пригодна для тестирования? | за 5 минут: меню, карточка, корзина, оформление |\n| Sanity | разумно ли работает то, что поменяли? | поправили сумму — проверили сумму и количество |\n| Ретест | исправлен ли **этот** баг? | повторили шаги своего бага на новой версии |\n| Регресс | не сломалось ли то, что **работало**? | прогнали набор старых кейсов раздела |\n\n### Регрессионный набор\nПрогонять всё каждый раз долго, поэтому набор выбирают **по риску**: главные функции, функции **рядом** с исправлениями, то, что раньше ломалось, и то, что поменялось. У каждого кейса — причина в одну строку. **Полный регресс** (все кейсы) — перед крупным релизом.\n\n### Регресс или новое правило\nПоведение в новой версии другое? Сначала открой требования новой версии. Правило изменилось — это **новая функция**, ожидание кейса обновляют. Правило прежнее, а работает хуже — **регрессионный баг**: «В 1.5 работало, в 2.0 — нет»."
