        "code": "",
        "codeNote": "",
        "more": "### Төрт тексеру — төрт сұрақ\n| Тексеру | Сұрақ | Мысал |\n|---|---|---|\n| Smoke | жаңа жинақ жалпы тестілеуге жарай ма? | 5 минутта: мәзір, карточка, себет, рәсімдеу |\n| Sanity | өзгергені дұрыс жұмыс істей ме? | соманы түзетті — сома мен санды тексердік |\n| Ретест | **осы** баг түзетілді ме? | жаңа нұсқада өз багымыздың қадамдарын қайталадық |\n| Регресс | **жұмыс істеген** нәрсе бұзылмады ма? | бөлімнің ескі кейстер жиынын өттік |\n\n### Регрессиялық жиын\nӘр жолы бәрін өту ұзаққа созылады, сондықтан жиынды **тәуекел бойынша** таңдайды: басты функциялар, түзетулердің **жанындағы** функциялар, бұрын бұзылғандар және өзгергендер. Әр кейстің бір жолдық себебі бар. **Толық регресс** (барлық кейс) — ірі релиз алдында.\n\n### Регресс пе, жаңа ереже ме\nЖаңа нұсқада әрекет басқаша ма? Алдымен жаңа нұсқаның талаптарын аш. Ереже өзгерген — бұл **жаңа функция**, кейс күтуін жаңартады. Ереже бұрынғыдай, ал нашар жұмыс істейді — **регрессиялық баг**: «1.5-те жұмыс істеді, 2.0-де — жоқ»."
