        "more": "### Алдымен маңыздысы\nУақыт әрдайым тексергің келгеннен аз. Сондықтан тексерулерді **тәуекел бойынша** ретке келтіреді:\n1. Сатып алушының басты жолы және қатесі ақшаға тұратын жерлер: мәзір, себетке қосу, рәсімдеу.\n2. Жиі қолданылатын, бірақ қатесін айналып өтуге болатын нәрселер: тіл ауыстыру, беттер арасындағы сілтемелер.\n3. Қосалқы нәрселер: белгішелер, анимация, ұсақ мәтіндер.\n\n### Таңдауыңды қалай түсіндіру керек\nӘр функцияға **ықтималдықты** (жиі бұзыла ма не қолданыла ма) және **салдарды** (қонақ не жоғалтады) ата. Мысал: «Рәсімдеуді бірінші тексеремін: оны әр сатып алушы пайдаланады, онсыз тапсырыс кофеханаға жетпейді».\n\n### Үлгермегенің\nТексерілмегені үнсіз жоғалмайды: оны есепке қалған тәуекел ретінде жаз. «Тіл ауыстыруды тексермедім» — адал әрі пайдалы нәтиже; тексерусіз «бәрі жұмыс істейді» — олай емес."
