        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Что такое хорошее доказательство\nДоказательство (Evidence) показывает проблему так, чтобы её понял человек, который её не видел. Это скриншот, короткое видео или нужный фрагмент ответа. Шаги и текст результата всё равно нужны: картинка не заменяет описание.\n\n### Как сделать скриншот\n- **Windows:** Win+Shift+S → выдели область → снимок в буфере обмена, вставь его Ctrl+V в сообщение.\n- **Телефон:** обычно одновременно кнопки питания и уменьшения громкости.\n- Для видео в Windows: Win+Alt+R (Xbox Game Bar) начинает и останавливает запись.\n\n### Что должно быть на снимке\n| Хорошо | Плохо |\n|---|---|\n| вся страница и адресная строка | обрезанная цифра без контекста |\n| отмечено место проблемы | непонятно, куда смотреть |\n| видна версия сайта или указана рядом | неизвестно, какая версия |\n| личные данные скрыты | на снимке настоящий телефон или адрес |\n\nНе редактируй снимок так, чтобы изменился факт. Если проблема видна только после нескольких действий, запиши короткое видео."
