        "code": "",
        "codeNote": "",
        "more": "### Жақсы дәлел деген не\nДәлел (Evidence) мәселені оны көрмеген адам түсінетіндей көрсетеді. Бұл — скриншот, қысқа бейне не жауаптың қажетті үзіндісі. Қадамдар мен нәтиже мәтіні бәрібір керек: сурет сипаттаманы алмастырмайды.\n\n### Скриншотты қалай жасау керек\n- **Windows:** Win+Shift+S → аймақты белгіле → сурет алмасу буферінде, оны хабарламаға Ctrl+V арқылы қой.\n- **Телефон:** әдетте қуат пен дыбысты азайту батырмалары бірге.\n- Windows-та бейне үшін: Win+Alt+R (Xbox Game Bar) жазуды бастайды және тоқтатады.\n\n### Суретте не болуы керек\n| Жақсы | Нашар |\n|---|---|\n| бүкіл бет және мекенжай жолағы | контекстсіз қиылған сан |\n| мәселе орны белгіленген | қайда қарау керегі түсініксіз |\n| сайт нұсқасы көрінеді не жанында жазылған | қай нұсқа екені белгісіз |\n| жеке деректер жасырылған | суретте нақты телефон не мекенжай |\n\nФактіні өзгертетіндей суретті өңдеме. Мәселе бірнеше әрекеттен кейін ғана көрінсе, қысқа бейне жаз."
