        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Как начать\n1. Открой [trello.com](https://trello.com) → **Sign up**. Регистрируйся на **свою почту**, не через Google, и подтверди адрес по письму или коду.\n2. **Create → Create board** — дай доске понятное название, например «QA — Айгерим».\n3. Создай списки (колонки) кнопкой **Add a list**: Backlog, To do, In progress, Review, Done. Ненужный список: «…» → **Archive this list**.\n4. **Add a card** — новая карточка. Перетащи карточку мышью в другую колонку, когда работа перешла в новое состояние.\n\nБесплатного тарифа хватает для личных и небольших командных досок: до 10 досок и до 10 участников в одном рабочем пространстве. Если Trello предлагает пробный платный период или оплату — для учёбы это не нужно.\n\n### Что писать в карточке\nОдна карточка — одна понятная задача. В названии — что сделать («Проверить переключение RU / KZ»), внутри карточки (нажми на неё) — подробности, ссылки и скриншоты. Не меняй чужие карточки без договорённости команды."
