        "more": "### Қалай бастау керек\n1. [trello.com](https://trello.com) аш → **Sign up**. **Өз поштаңмен** тіркел, Google арқылы емес, және мекенжайды хат не код арқылы раста.\n2. **Create → Create board** — тақтаға түсінікті атау бер, мысалы «QA — Айгерім».\n3. **Add a list** батырмасымен тізімдер (бағандар) жаса: Backlog, To do, In progress, Review, Done. Қажетсіз тізім: «…» → **Archive this list**.\n4. **Add a card** — жаңа карточка. Жұмыс жаңа күйге өткенде карточканы тінтуірмен басқа бағанға сүйре.\n\nЖеке және шағын командалық тақталарға тегін тариф жетеді: бір жұмыс кеңістігінде 10 тақтаға дейін және 10 қатысушыға дейін. Trello ақылы сынақ кезеңін не төлемді ұсынса — оқуға қажет емес.\n\n### Карточкаға не жазу керек\nБір карточка — бір түсінікті тапсырма. Атауында — не істеу керек («RU / KZ ауыстыруды тексеру»), карточка ішінде (оны бас) — толық мәлімет, сілтемелер мен скриншоттар. Команда келісімінсіз басқаның карточкасын өзгертпе."
