        "code": "",
        "codeNote": "",
        "more": "### Чек-лист — список покупок\nЧек-лист — список того, что проверить, **без** подробных шагов. Тест-кейс — рецепт с порядком действий, чек-лист — список покупок («молоко, хлеб»). Чек-лист быстрее, но рассчитан на того, кто знает продукт.\n\n| | Чек-лист | Тест-кейс |\n|---|---|---|\n| Внутри | одна строка на проверку | шаги, предусловия, ожидание |\n| Когда | быстрые и частые проверки, smoke | важная или сложная функция, новичок |\n| Пример | «Ссылка „В меню“ в пустой корзине открывает меню» | TC-CRT-003 с шагами |\n\n### Хороший пункт\n- **Одна проверяемая мысль**: на пункт можно ответить «да» или «нет». Плохо: «Корзина работает». Хорошо: «Ссылка „В меню“ в пустой корзине открывает меню».\n- **Функциональные** пункты — что работает; **UI-пункты** — как выглядит (тексты не обрезаны, кнопки одного стиля).\n- Структура: раздел → пункт → статус → комментарий. У каждого Failed и Blocked — комментарий, что увидел.\n- Если дальше идти нельзя, следующие пункты — **Blocked** с причиной, а не Failed.\n- Хороший чек-лист разные люди проходят одинаково. Если сосед понял пункт иначе — пункт уточняют. Сложную проверку, которую нельзя выполнить без пояснений, превращают в тест-кейс.",
