        "code": "",
        "codeNote": "",
        "more": "### Чек-лист — сатып алу тізімі\nЧек-лист — нені тексеру керегінің егжей-тегжейлі қадамдар**сыз** тізімі. Тест-кейс — әрекет реті бар рецепт, чек-лист — сатып алу тізімі («сүт, нан»). Чек-лист тезірек, бірақ өнімді білетін адамға арналған.\n\n| | Чек-лист | Тест-кейс |\n|---|---|---|\n| Ішінде | бір тексеруге бір жол | қадамдар, алғышарттар, күту |\n| Қашан | жылдам әрі жиі тексерулер, smoke | маңызды не күрделі функция, жаңа адам |\n| Мысал | «Бос себеттегі „Мәзірге“ сілтемесі мәзірді ашады» | қадамдары бар TC-CRT-003 |\n\n### Жақсы тармақ\n- **Бір тексерілетін ой**: тармаққа «иә» не «жоқ» деп жауап беруге болады. Нашар: «Себет жұмыс істейді». Жақсы: «Бос себеттегі „Мәзірге“ сілтемесі мәзірді ашады».\n- **Функционалдық** тармақтар — не жұмыс істейді; **UI-тармақтар** — қалай көрінеді (мәтіндер қиылмаған, батырмалар бір стильде).\n- Құрылым: бөлім → тармақ → мәртебе → пікір. Әр Failed пен Blocked-та — не көргені туралы пікір.\n- Әрі қарай жүру мүмкін болмаса, келесі тармақтар — Failed емес, себебі бар **Blocked**.\n- Жақсы чек-листі әртүрлі адамдар бірдей өтеді. Көрші тармақты басқаша түсінсе — тармақты нақтылайды. Түсіндірмесіз орындауға болмайтын күрделі тексеруді тест-кейске айналдырады.",
