        "steps": [],
        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Три вопроса к продукту\n1. **Кто пользуется?** — гость, который заказывает кофе с телефона или компьютера.\n2. **Какие функции главные?** — те, без которых продукт бессмыслен: для магазина это каталог, корзина и оформление.\n3. **Что будет, если функция сломается?** — это и есть риск.\n\n### Карта функций\nКарта — как оглавление книги: в центре продукт, ветки — разделы (Меню, Карточка, Корзина, Оформление, Общее), на ветках — функции («добавить в корзину», «переключить язык»). Рисовать можно на бумаге, в заметках или в любом сервисе для схем. Карта помогает ничего не забыть и поделить работу: каждый берёт свою ветку.\n\n### Риск\n**Риск = вероятность × последствия.** Оплата ломается редко, но последствия огромны — риск высокий. Иконка в подвале может сломаться, но почти ничему не мешает — риск низкий. Для каждой функции на карте полезно записать: что потеряет пользователь, если она не работает, и какие виды проверки ей нужны."
