        "more": "### Роли в команде\n| Роль | Что делает | Вопрос, на который отвечает |\n|---|---|---|\n| Продакт-менеджер | решает, что и зачем делаем | «Что нужно гостям?» |\n| Аналитик | уточняет и записывает правила | «Как именно это должно работать?» |\n| Дизайнер | рисует экраны и состояния | «Как это выглядит?» |\n| Разработчик | пишет код | «Как это сделать?» |\n| Тестировщик (QA) | проверяет качество на каждом этапе | «Работает ли это по правилам и понятны ли правила?» |\n\nОдин человек может совмещать роли, особенно в маленькой команде.\n\n### К кому идти с вопросом\nНепонятно правило — к аналитику или заказчику (на курсе — к ментору). Непонятно, как должно выглядеть, — к дизайнеру или макету. Нашёл расхождение — оформляешь баг, разработчик его исправляет. Тестировщик **не придумывает** бизнес-правила сам: если правила нет, он задаёт вопрос.\n\nРешение о выпуске принимает продакт, а не тестировщик и не разработчик: это одна команда с разными ролями."
