        "more": "### Командадағы рөлдер\n| Рөл | Не істейді | Қай сұраққа жауап береді |\n|---|---|---|\n| Продакт-менеджер | не және не үшін жасайтынын шешеді | «Қонақтарға не керек?» |\n| Талдаушы | ережелерді нақтылап, жазады | «Бұл нақты қалай жұмыс істеуі керек?» |\n| Дизайнер | экрандар мен күйлерді салады | «Бұл қалай көрінеді?» |\n| Әзірлеуші | код жазады | «Мұны қалай жасаймыз?» |\n| Тестілеуші (QA) | әр кезеңде сапаны тексереді | «Бұл ереже бойынша жұмыс істей ме және ережелер түсінікті ме?» |\n\nБір адам бірнеше рөлді атқаруы мүмкін, әсіресе шағын командада.\n\n### Сұрақпен кімге бару керек\nЕреже түсініксіз — талдаушыға не тапсырыс берушіге (курста — менторға). Қалай көрінуі керегі түсініксіз — дизайнерге не макетке. Айырмашылық таптың — баг рәсімдейсің, әзірлеуші оны түзетеді. Тестілеуші бизнес-ережелерді **өзі ойлап таппайды**: ереже жоқ болса, сұрақ қояды.\n\nШығару туралы шешімді тестілеуші де, әзірлеуші де емес, продакт қабылдайды: бұл әртүрлі рөлдері бар бір команда."
