        "steps": [],
        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Smoke — «можно ли тестировать дальше?»\nSmoke-тест — короткая проверка самых главных путей новой версии. Название пришло от проверки техники: включили прибор — не пошёл ли дым. Для кофейни это меню → карточка → корзина → оформление, 5–10 минут. Если smoke не прошёл (например, меню не открывается), подробно тестировать остальное нет смысла: сначала сообщаем о проблеме.\n\n### Sanity — «разумно ли работает то, что поменяли?»\nSanity — узкая проверка одной изменённой области после небольшой правки. Поменяли расчёт количества — проверяем количество и сумму рядом с ним, а не весь сайт.\n\n| | Smoke | Sanity |\n|---|---|---|\n| Когда | новая версия или сборка | после небольшой правки |\n| Что | главные пути всего продукта | одна изменённая область |\n| Ширина | широко, но неглубоко | узко, но внимательнее |\n\nТочные границы smoke и sanity команды договаривают по-своему. Ретест и регресс — отдельные проверки, их разберём позже."
