        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Smoke — «әрі қарай тексеруге бола ма?»\nSmoke-тест — жаңа нұсқаның ең басты жолдарын қысқа тексеру. Атауы техниканы тексеруден шыққан: құрылғыны қостық — түтін шықпады ма. Кофехана үшін бұл мәзір → карточка → себет → рәсімдеу, 5–10 минут. Smoke өтпесе (мысалы, мәзір ашылмаса), қалғанын егжей-тегжейлі тексерудің мәні жоқ: алдымен мәселе туралы хабарлаймыз.\n\n### Sanity — «өзгергені дұрыс жұмыс істей ме?»\nSanity — шағын түзетуден кейін бір өзгерген аймақты тар тексеру. Сан есептеуін өзгертті — бүкіл сайтты емес, санды және оның жанындағы соманы тексереміз.\n\n| | Smoke | Sanity |\n|---|---|---|\n| Қашан | жаңа нұсқа не жинақ | шағын түзетуден кейін |\n| Нені | бүкіл өнімнің басты жолдары | бір өзгерген аймақ |\n| Ені | кең, бірақ терең емес | тар, бірақ мұқият |\n\nSmoke пен sanity шекарасын командалар өзінше келіседі. Ретест пен регресс — бөлек тексерулер, оларды кейін талдаймыз."
