        "more": "### Предусловие — состояние, данные — значения\n**Предусловие** — что должно быть **до** первого шага: «в корзине один латте», «открыта версия 1.0». **Тестовые данные** — значения, которые используешь в шагах: имя «Айгерим», телефон «+7 700 000 00 01», количество 2, строка поиска «латте».\n\n| Ситуация | Предусловие | Тестовые данные |\n|---|---|---|\n| Удалить единственный товар | в корзине один латте | — |\n| Оформить заказ | в корзине есть напиток | имя, телефон, адрес |\n| Открыть меню | — | — |\n\n### Правила\n- Оба поля **необязательны**: пиши их, только когда без них проверку нельзя повторить. Пустое поле удали, а не заполняй «нет».\n- Тестовые данные — это не только логин и пароль. Напиток, размер и количество — тоже данные.\n- Используй **вымышленные** данные: не свой телефон, адрес или почту.\n- Данные готовят **заранее**, в таблице: поле → значение → валидное или нет → что ожидаем."
