        "codeNote": "",
        "more": "### Алғышарт — күй, деректер — мәндер\n**Алғышарт** — бірінші қадамға **дейін** не болуы керек: «себетте бір латте», «1.0 нұсқасы ашық». **Тест деректері** — қадамдарда қолданатын мәндер: аты «Айгерім», телефон «+7 700 000 00 01», саны 2, іздеу жолы «латте».\n\n| Жағдай | Алғышарт | Тест деректері |\n|---|---|---|\n| Жалғыз тауарды жою | себетте бір латте | — |\n| Тапсырыс беру | себетте сусын бар | аты, телефон, мекенжай |\n| Мәзірді ашу | — | — |\n\n### Ережелер\n- Екі өріс те **міндетті емес**: оларсыз тексеруді қайталау мүмкін болмағанда ғана жаз. Бос өрісті «жоқ» деп толтырма, өшір.\n- Тест деректері — тек логин мен құпиясөз емес. Сусын, өлшем және саны да — деректер.\n- **Ойдан шығарылған** деректерді қолдан: өз телефоныңды, мекенжайыңды не поштаңды емес.\n- Деректерді **алдын ала**, кестеде дайындайды: өріс → мән → жарамды ма, жоқ па → не күтеміз."
