        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Зачем ревью\nАвтор знает, что имел в виду, поэтому не видит пробелов в своём тексте. Ревью (Review) — другой человек читает и выполняет работу **без устных подсказок**. Если он запнулся, текст нужно уточнить.\n\n### Как проводить\n1. Автор отдаёт текст и **молчит**.\n2. Ревьюер выполняет кейс или шаги репорта строго по тексту.\n3. Ревьюер называет **конкретное** место: «В шаге 3 не указан напиток — какой выбрать?»\n4. Автор исправляет текст и сохраняет ID.\n\n### Чек-лист качества тест-кейса\n- понятное название;\n- нужные предусловия;\n- конкретные шаги, по одному действию;\n- проверяемый ожидаемый результат из правила;\n- одна проверка в кейсе;\n- в наборе есть негативные и граничные кейсы.\n\n### Тон\nКритикуем запись, а не человека. «Всё плохо» не помогает; «в шаге 2 непонятно, из какой корзины удалять» — помогает. Ожидание не меняем без проверки требования."
