        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Проверяем то самое место\nРетест — проверка **конкретного** бага после исправления: **те же шаги, те же данные, то же окружение, новая версия**. Как врач после лечения проверяет именно больное место.\n\n| Результат | Что делаем |\n|---|---|\n| проблемы нет | **Closed** + комментарий «Проверено в версии …, браузер …» |\n| проблема та же | **Reopened** + новый факт и скриншот |\n| рядом другая проблема | старый — по результату, **новый баг** отдельно |\n| проверить нельзя | статус не меняем, пишем «Ретест невозможен: причина» |\n\n### Частые ошибки\n- Закрыть баг сразу после слова Fixed — без проверки.\n- Повторить «примерно похоже» с другими данными или в другом браузере.\n- Переоткрыть старый баг из-за новой, другой проблемы.\n- Назвать ретестом обычный повтор на **старой** версии: без новой сборки ретест не выполнен.\n\nНа портале новой сборкой для багов версии 1.5 служит версия **2.0**: в ней отдельные данные, поэтому подготовку из предусловий повторяют заново."
