        "more": "### Дәл сол жерді тексереміз\nРетест — түзетуден кейін **нақты** багты тексеру: **сол қадамдар, сол деректер, сол орта, жаңа нұсқа**. Дәрігер емдегеннен кейін дәл ауырған жерді тексереді.\n\n| Нәтиже | Не істейміз |\n|---|---|\n| мәселе жоқ | **Closed** + «Нұсқа …, браузер … бойынша тексерілді» пікірі |\n| мәселе сол | **Reopened** + жаңа факт пен скриншот |\n| жанында басқа мәселе | ескісі — нәтижесі бойынша, **жаңа баг** бөлек |\n| тексеру мүмкін емес | мәртебені өзгертпейміз, «Ретест мүмкін емес: себебі» деп жазамыз |\n\n### Жиі қателер\n- Fixed сөзінен кейін бірден тексерусіз жабу.\n- Басқа деректермен не басқа браузерде «шамамен ұқсас» қайталау.\n- Жаңа, басқа мәселеге бола ескі багты қайта ашу.\n- **Ескі** нұсқадағы жай қайталауды ретест деп атау: жаңа жинақсыз ретест орындалмады.\n\nПорталда 1.5 нұсқасының багтары үшін жаңа жинақ — **2.0** нұсқасы: онда деректер бөлек, сондықтан алғышарттардағы дайындықты қайта жасайды."
