        "template": "",
        "code": "",
        "codeNote": "",
        "more": "### Цепочка показа\nРассказ о работе строится по цепочке: **правило → действие → доказательство → вывод**. «Правило CRT-05 говорит… Я сделал… Вот скриншот… Значит…» — так слушатель видит, что вывод доказан.\n\n### Выступление на защите (около 2 минут на раздел)\n| Часть | Что сказать |\n|---|---|\n| Раздел | что входило в объём, версии |\n| Что сделал | план, сколько кейсов и прогонов |\n| Цифры | Pass rate, баги по серьёзности, сколько закрыто |\n| Самый интересный баг | по цепочке, с показом карточки |\n| Вывод | готов ли раздел, что не проверено |\n\n### Ответы на вопросы\n- Вопрос о правиле — назови номер и текст правила.\n- Вопрос о доказательстве — покажи карточку и скриншот.\n- Вопрос об оценке — объясни через влияние на гостя.\n- Не знаешь — «Не проверял, могу проверить». Это лучше выдумки.\n\n### Подготовка\nОткрой ссылки заранее, сохрани скриншоты на случай без интернета, объясняй своими словами (ответ, прочитанный за ИИ, не засчитывается), проверь ссылки в окне инкогнито перед передачей."
