        "more": "### Что изменилось между версиями\nСравнение версий отвечает на вопрос «что поменялось и как это проверить». У qala coffe три версии: **1.0**, **1.5** и **2.0**, у каждой свои требования, каталог и данные.\n\n| Отличие в новой версии | Это | Что делаем |\n|---|---|---|\n| правило изменилось, сайт работает по новому | новая функция | обновляем ожидание кейса |\n| исправлен известный баг | исправление | ретест: Closed |\n| работавшее раньше стало хуже, правило то же | регрессия | регрессионный баг с обеими версиями |\n| появился новый раздел | новая функция | новые кейсы |\n\n### Правила сравнения\nСравнивай **одинаковые шаги** с **одинаковыми данными** в **одном браузере** — меняется только версия. Всегда записывай обе версии. Без исправленной сборки успешный ретест не заявляют."
