        "code": "",
        "codeNote": "",
        "more": "### Нұсқалар арасында не өзгерді\nНұсқаларды салыстыру «не өзгерді және оны қалай тексеру керек» деген сұраққа жауап береді. qala coffe-дің үш нұсқасы бар: **1.0**, **1.5** және **2.0**, әрқайсысының өз талаптары, каталогы және деректері.\n\n| Жаңа нұсқадағы айырмашылық | Бұл | Не істейміз |\n|---|---|---|\n| ереже өзгерді, сайт жаңасымен жұмыс істейді | жаңа функция | кейс күтуін жаңартамыз |\n| белгілі баг түзетілді | түзету | ретест: Closed |\n| бұрын жұмыс істеген нашарлады, ереже сол | регрессия | екі нұсқасы бар регрессиялық баг |\n| жаңа бөлім пайда болды | жаңа функция | жаңа кейстер |\n\n### Салыстыру ережелері\n**Бірдей қадамдарды** **бірдей деректермен** **бір браузерде** салыстыр — тек нұсқа өзгереді. Әрдайым екі нұсқаны да жаз. Түзетілген жинақсыз сәтті ретест туралы айтпайды."
